"""Demo 1: Gaussian binomial coefficients and the dual Pascal recurrences.

Represents polynomials in q as integer coefficient tuples and builds the
q-Pascal triangle bottom-up via  [n,k] = [n-1,k-1] + q^k [n-1,k]  (division-free,
hence integral).  Verifies both Pascal recurrences (P1) and (P2).
"""
from __future__ import annotations
from typing import Dict, List, Tuple

Poly = Tuple[int, ...]

def trim(p: Poly) -> Poly:
    c: List[int] = list(p)
    while len(c) > 1 and c[-1] == 0: c.pop()
    return tuple(c)

def padd(a: Poly, b: Poly) -> Poly:
    n = max(len(a), len(b))
    return trim(tuple((a[i] if i < len(a) else 0) + (b[i] if i < len(b) else 0) for i in range(n)))

def pmul(a: Poly, b: Poly) -> Poly:
    out = [0] * (len(a) + len(b) - 1)
    for i, ai in enumerate(a):
        for j, bj in enumerate(b): out[i + j] += ai * bj
    return trim(tuple(out))

def mono(d: int) -> Poly: return tuple([0] * d + [1])

def gauss_binom(n: int, k: int) -> Poly:
    if k < 0 or k > n: return (0,)
    T: Dict[Tuple[int, int], Poly] = {}
    for nn in range(n + 1):
        for kk in range(nn + 1):
            T[(nn, kk)] = (1,) if kk in (0, nn) else padd(T[(nn-1, kk-1)], pmul(mono(kk), T[(nn-1, kk)]))
    return T[(n, k)]

def show(p: Poly) -> str:
    return " + ".join(f"{c}q^{i}" if i > 1 else (f"{c}q" if i == 1 else f"{c}")
                      for i, c in enumerate(p) if c) or "0"

if __name__ == "__main__":
    for n in range(6):
        print("  ".join(show(gauss_binom(n, k)) for k in range(n + 1)))
    for n in range(1, 9):
        for k in range(n + 1):
            lhs = gauss_binom(n, k)
            p1 = padd(gauss_binom(n-1, k-1), pmul(mono(k), gauss_binom(n-1, k)))
            p2 = padd(pmul(mono(n-k), gauss_binom(n-1, k-1)), gauss_binom(n-1, k))
            assert lhs == p1 == p2
    print("Both Pascal recurrences verified up to n=8.")

"""Demo 2: The absorption identity and the filtration layer recursion.

The absorption identity  [N,k+1](1-q^{k+1}) = [N,k](1-q^{N-k})  fixes the exact
ratio between adjacent graded pieces of the conjectured filtration.  We verify it
and use it to regenerate the whole row of coefficients from [N,0]=1 by exact
polynomial division in Z[q].
"""
from __future__ import annotations
from typing import List, Tuple

Poly = Tuple[int, ...]

def trim(p: Poly) -> Poly:
    c = list(p)
    while len(c) > 1 and c[-1] == 0: c.pop()
    return tuple(c)

def pmul(a: Poly, b: Poly) -> Poly:
    out = [0] * (len(a) + len(b) - 1)
    for i, ai in enumerate(a):
        for j, bj in enumerate(b): out[i + j] += ai * bj
    return trim(tuple(out))

def one_minus_qe(e: int) -> Poly:
    c = [0] * (e + 1); c[0] = 1; c[e] = -1
    return trim(tuple(c))

def pdiv_exact(num: Poly, den: Poly) -> Poly:
    """Exact division num/den in Z[q]; asserts zero remainder."""
    num = list(num); q: List[int] = [0] * (len(num) - len(den) + 1)
    for i in range(len(q) - 1, -1, -1):
        coef = num[i + len(den) - 1] // den[-1]
        q[i] = coef
        for j, dj in enumerate(den): num[i + j] -= coef * dj
    assert all(x == 0 for x in num), "non-exact division"
    return trim(tuple(q))

def mono(d: int) -> Poly: return tuple([0] * d + [1])

def gauss_binom(n: int, k: int) -> Poly:
    if k < 0 or k > n: return (0,)
    from functools import lru_cache
    T = {}
    def padd(a, b):
        m = max(len(a), len(b))
        return trim(tuple((a[i] if i < len(a) else 0)+(b[i] if i < len(b) else 0) for i in range(m)))
    for nn in range(n + 1):
        for kk in range(nn + 1):
            T[(nn, kk)] = (1,) if kk in (0, nn) else padd(T[(nn-1, kk-1)], pmul(mono(kk), T[(nn-1, kk)]))
    return T[(n, k)]

if __name__ == "__main__":
    N = 6
    row = [(1,)]
    for k in range(N):
        nxt = pdiv_exact(pmul(row[-1], one_minus_qe(N - k)), one_minus_qe(k + 1))
        row.append(nxt)
        assert nxt == gauss_binom(N, k + 1)
    print(f"Row N={N} reconstructed purely from absorption:")
    for k, p in enumerate(row):
        print(f"  [{N},{k}] =", " + ".join(f"{c}q^{i}" if i else f"{c}" for i, c in enumerate(p) if c))
    print("Absorption-driven reconstruction matches direct computation.")

"""Demo 3: The categorified product rule (Rel2) and trinomial reciprocity.

Lusztig's divided powers multiply by  E^(a) E^(b) = [a+b,a]_q E^(a+b).  We verify
the single-step splitting of the structure constant and the trinomial reciprocity
[a+b+c,a][b+c,b] = [a+b+c,c][a+b,a] that encodes associativity of the product.
"""
from __future__ import annotations
from typing import Dict, Tuple

Poly = Tuple[int, ...]

def trim(p: Poly) -> Poly:
    c = list(p)
    while len(c) > 1 and c[-1] == 0: c.pop()
    return tuple(c)

def padd(a: Poly, b: Poly) -> Poly:
    n = max(len(a), len(b))
    return trim(tuple((a[i] if i < len(a) else 0)+(b[i] if i < len(b) else 0) for i in range(n)))

def pmul(a: Poly, b: Poly) -> Poly:
    out = [0] * (len(a) + len(b) - 1)
    for i, ai in enumerate(a):
        for j, bj in enumerate(b): out[i + j] += ai * bj
    return trim(tuple(out))

def mono(d: int) -> Poly: return tuple([0] * d + [1])

def gauss_binom(n: int, k: int) -> Poly:
    if k < 0 or k > n: return (0,)
    T: Dict[Tuple[int, int], Poly] = {}
    for nn in range(n + 1):
        for kk in range(nn + 1):
            T[(nn, kk)] = (1,) if kk in (0, nn) else padd(T[(nn-1, kk-1)], pmul(mono(kk), T[(nn-1, kk)]))
    return T[(n, k)]

if __name__ == "__main__":
    # single-step splitting of the Rel2 structure constant
    for a in range(1, 8):
        for b in range(8):
            n = a + b
            assert gauss_binom(n, a) == padd(gauss_binom(n-1, a-1), pmul(mono(a), gauss_binom(n-1, a)))
    print("Rel2 structure-constant splitting verified (a,b up to 7).")
    # trinomial reciprocity (associativity)
    for a in range(6):
        for b in range(6):
            for c in range(6):
                assert pmul(gauss_binom(a+b+c, a), gauss_binom(b+c, b)) == \
                       pmul(gauss_binom(a+b+c, c), gauss_binom(a+b, a))
    print("Trinomial reciprocity verified (a,b,c up to 5).")

