from typing import Dict, List, Tuple
Poly = Tuple[int, ...]

def _trim(p: Poly) -> Poly:
    c: List[int] = list(p)
    while len(c) > 1 and c[-1] == 0: c.pop()
    return tuple(c)

def _add(a: Poly, b: Poly) -> Poly:
    n = max(len(a), len(b))
    return _trim(tuple((a[i] if i < len(a) else 0)+(b[i] if i < len(b) else 0) for i in range(n)))

def _mul(a: Poly, b: Poly) -> Poly:
    out = [0] * (len(a) + len(b) - 1)
    for i, ai in enumerate(a):
        for j, bj in enumerate(b): out[i + j] += ai * bj
    return _trim(tuple(out))

def q_pascal(n_max: int) -> Dict[Tuple[int, int], Poly]:
    """Tabulate all Gaussian binomials [n,k]_q for 0<=k<=n<=n_max."""
    T: Dict[Tuple[int, int], Poly] = {}
    for n in range(n_max + 1):
        for k in range(n + 1):
            if k == 0 or k == n:
                T[(n, k)] = (1,)
            else:
                qk = tuple([0] * k + [1])                    # q^k
                T[(n, k)] = _add(T[(n-1, k-1)], _mul(qk, T[(n-1, k)]))
    return T

