Poly = Tuple[int, ...]

def _trim(p: Poly) -> Poly:
    c = list(p)
    while len(c) > 1 and c[-1] == 0: c.pop()
    return tuple(c)

def _mul(a: Poly, b: Poly) -> Poly:
    out = [0] * (len(a) + len(b) - 1)
    for i, ai in enumerate(a):
        for j, bj in enumerate(b): out[i + j] += ai * bj
    return _trim(tuple(out))

def _div_exact(num: Poly, den: Poly) -> Poly:
    num = list(num); q: List[int] = [0] * (len(num) - len(den) + 1)
    for i in range(len(q) - 1, -1, -1):
        c = num[i + len(den) - 1] // den[-1]; q[i] = c
        for j, dj in enumerate(den): num[i + j] -= c * dj
    assert all(x == 0 for x in num)
    return _trim(tuple(q))

def _one_minus_qe(e: int) -> Poly:
    c = [0] * (e + 1); c[0] = 1; c[e] = -1
    return _trim(tuple(c))

def absorption_row(N: int) -> List[Poly]:
    """Reconstruct the row [N,0..N]_q using only the absorption identity."""
    row: List[Poly] = [(1,)]
    for k in range(N):
        row.append(_div_exact(_mul(row[-1], _one_minus_qe(N - k)), _one_minus_qe(k + 1)))
    return row

