from math import comb
from typing import Dict, Tuple
Poly = Tuple[int, ...]

def _eval(p: Poly, q: int) -> int:
    return sum(c * q ** i for i, c in enumerate(p))

def audit(table: Dict[Tuple[int, int], Poly], n_max: int) -> bool:
    """Certify Hermite reciprocity and the q=1 specialization on a finite window."""
    for n in range(n_max + 1):
        for k in range(n + 1):
            if table[(n, k)] != table[(n, n - k)]:
                return False
            if _eval(table[(n, k)], 1) != comb(n, k):
                return False
    return True

