"""Visualization 2: Coefficient profiles (unimodality) of [n,k]_q.

Each Gaussian binomial [n,k]_q has a symmetric, unimodal coefficient sequence.
We plot these profiles for fixed n=12 and several k, illustrating self-duality.
"""
import matplotlib.pyplot as plt

def trim(p):
    c = list(p)
    while len(c) > 1 and c[-1] == 0: c.pop()
    return tuple(c)

def add(a, b):
    m = max(len(a), len(b))
    return trim(tuple((a[i] if i < len(a) else 0)+(b[i] if i < len(b) else 0) for i in range(m)))

def mul(a, b):
    out = [0]*(len(a)+len(b)-1)
    for i, ai in enumerate(a):
        for j, bj in enumerate(b): out[i+j] += ai*bj
    return trim(tuple(out))

def gb(n, k, T={}):
    if not T:
        for nn in range(13):
            for kk in range(nn+1):
                T[(nn,kk)] = (1,) if kk in (0,nn) else add(T[(nn-1,kk-1)], mul(tuple([0]*kk+[1]), T[(nn-1,kk)]))
    return T[(n, k)]

fig, ax = plt.subplots(figsize=(8, 5))
for k in [2, 4, 6]:
    p = gb(12, k)
    ax.plot(range(len(p)), p, marker="o", label=f"[12,{k}]_q")
ax.set_xlabel("degree of q"); ax.set_ylabel("coefficient")
ax.set_title("Symmetric, unimodal coefficient profiles of Gaussian binomials")
ax.legend()
plt.tight_layout()
plt.savefig("viz_coefficient_profiles.png", dpi=150)
print("saved viz_coefficient_profiles.png")
